// --------------------------------------------------------------
// Quaternion rotation applied to a complex SDF (Mandelbulb)
// Optimized: quaternion -> matrix once per frame
// --------------------------------------------------------------
vec4 quatFromAxisAngle(vec3 axis, float angle) {
    float h = angle * 0.5;
    float s = sin(h);
    return vec4(axis * s, cos(h));
}

mat3 quatToMat3(vec4 q) {
    float x = q.x, y = q.y, z = q.z, w = q.w;
    float x2 = x + x, y2 = y + y, z2 = z + z;
    float xx = x * x2, yy = y * y2, zz = z * z2;
    float xy = x * y2, xz = x * z2, yz = y * z2;
    float wx = w * x2, wy = w * y2, wz = w * z2;

    return mat3(
        1.0 - (yy + zz), xy - wz,        xz + wy,
        xy + wz,        1.0 - (xx + zz), yz - wx,
        xz - wy,        yz + wx,         1.0 - (xx + yy)
    );
}

// Mandelbulb SDF
float mandelbulb(vec3 p) {
    vec3 z = p;
    float dr = 1.0;
    float r = 0.0;

    for (int i = 0; i < 8; i++) {
        r = length(z);
        if (r > 2.0) break;

        // power 8 bulb
        float theta = acos(z.z/r);
        float phi   = atan(z.y, z.x);
        float zr    = pow(r, 8.0);
        dr = pow(r, 7.0) * 8.0 * dr + 1.0;

        theta *= 8.0;
        phi   *= 8.0;

        z = zr * vec3(
            sin(theta)*cos(phi),
            sin(theta)*sin(phi),
            cos(theta)
        ) + p;
    }

    return 0.5 * log(r) * r / dr;
}

mat3 ROT; // global rotation matrix

float map(vec3 p) {
    p = ROT * p;
    return mandelbulb(p);
}

// Raymarch
float march(vec3 ro, vec3 rd) {
    float t = 0.0;
    for (int i=0; i<100; i++) {
        vec3 p = ro + t * rd;
        float d = map(p);
        if (d < 0.001) break;
        t += d;
        if (t > 20.0) break;
    }
    return t;
}

vec3 normal(vec3 p) {
    vec2 e = vec2(0.001, 0.0);
    return normalize(vec3(
        map(p+e.xyy)-map(p-e.xyy),
        map(p+e.yxy)-map(p-e.yxy),
        map(p+e.yyx)-map(p-e.yyx)
    ));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5*iResolution.xy)/iResolution.y;

    vec3 ro = vec3(0.0, 0.0, 4.0);
    vec3 rd = normalize(vec3(uv, -1.5));

    // build quaternion once
    vec3 axis = normalize(vec3(sin(iTime*0.3), 1.0, cos(iTime*0.25)));
    float angle = iTime * 0.4;
    vec4 q = quatFromAxisAngle(axis, angle);
    ROT = quatToMat3(q);   // global optimized matrix

    float t = march(ro, rd);
    vec3 col = vec3(0.0);

    if (t < 20.0) {
        vec3 p = ro + t * rd;
        vec3 n = normal(p);

        // simple lighting
        vec3 light = normalize(vec3(0.6, 0.7, -0.3));
        float diff = max(dot(n, light), 0.0);
        col = vec3(diff) * 1.5;
    }

    fragColor = vec4(pow(col, vec3(0.4545)), 1.0);
}
